import sys
import types
import unittest.mock as mock

from dspy.clients.databricks import DatabricksProvider, TrainingJobDatabricks


class _Status:
    def __init__(self, display_name):
        self.display_name = display_name


class _Run:
    def __init__(self, status):
        self.status = status


# Register fake `databricks.model_training.foundation_model` module so that
# `from databricks.model_training import foundation_model as fm` succeeds.
top = types.ModuleType("databricks")
top.__path__ = []
parent = types.ModuleType("databricks.model_training")
parent.__path__ = []
foundation_model = types.ModuleType("databricks.model_training.foundation_model")
foundation_model.fm = None
sys.modules["databricks"] = top
sys.modules["databricks.model_training"] = parent
sys.modules["databricks.model_training.foundation_model"] = foundation_model

import databricks.model_training.foundation_model as fm_mod


def set_status_sequence(sequence):
    """fm.get returns each status in `sequence` in order, last one repeated."""
    state = {"i": 0}

    def create(**kwargs):
        return _Run(_Status(sequence[0]))

    def get(run):
        i = min(state["i"], len(sequence) - 1)
        state["i"] += 1
        return _Run(_Status(sequence[i]))

    fm_mod.create = create
    fm_mod.get = get


def run_case(sequence, expect_raise):
    job = TrainingJobDatabricks()
    sleep_calls = []

    def fake_sleep(seconds):
        sleep_calls.append(seconds)
        if len(sleep_calls) > 50:
            raise RuntimeError("BUG: too many sleeps, job never resolved")

    set_status_sequence(sequence)

    with mock.patch.object(DatabricksProvider, "upload_data", return_value="/Volumes/x/y/z/data.jsonl"), mock.patch(
        "dspy.clients.databricks.time.sleep", side_effect=fake_sleep
    ):
        try:
            result = DatabricksProvider.finetune(
                job=job,
                model="meta-llama/Llama-3.2-1B",
                train_data=[{"messages": [{"role": "user", "content": "hi"}]}],
                train_data_format="chat",
                train_kwargs={
                    "train_data_path": "/Volumes/main/chenmoney/testing/dspy_testing",
                    "register_to": "main.chenmoney.finetuned_model",
                    "skip_deploy": True,
                },
            )
        except ValueError as e:
            if expect_raise:
                print(f"OK: raised ValueError for sequence={sequence}: {e}")
                return
            print(f"FAIL: unexpected ValueError for sequence={sequence}: {e}")
            raise SystemExit(1)

        if expect_raise:
            print(f"FAIL: expected ValueError for sequence={sequence}, got result={result}, sleeps={sleep_calls}")
            raise SystemExit(1)
        print(f"OK: no error for sequence={sequence}, result={result}, sleeps={sleep_calls}")


run_case(["Completed"], expect_raise=False)
run_case(["Failed"], expect_raise=True)
run_case(["Running", "Running", "Completed"], expect_raise=False)
run_case(["Failed", "Completed"], expect_raise=True)  # failed must not be papered over by later status
